P=pathlib.Path(__file__).resolve().parent;ROOT=P.parents[2];M=ROOT/'agent-artifacts/manifests/v2.2/production_manifest_masterplan_v2_2.json';m=json.loads(M.read_text());bp={r['plannedId']:r for r in m['manifest'][:25]};cases=[]
