def O(text,q,ex,tempt,when,pattern):return dict(text=text,decisionQuality=q,isBest=q==1,reasoningPattern=pattern,failurePattern=None if q==1 else pattern,explanation=ex,whyTempting=tempt,whyNotBest=('Это наиболее обоснованный вариант в заданных условиях; границы применимости указаны ниже.' if q==1 else ex),whenItWouldBeBest=when)
def add(n,title,ctx,question,opts,insight,model,facts,source,rationale):
 r=bp[f'TC-{n:03}'];c={k:r[k] for k in ['partId','topicId','domain','requiredLevel','primaryPattern','secondaryPatterns','trainingEligible','assessmentEligible','scenarioFamilyId']};c.update(id=r['plannedId'],revision=1,type='single-best',title=title,sourceTopicExplanation=source,context=ctx,question=question,options=[dict(o,id=chr(65+i)) for i,o in enumerate(opts)],keyInsight=insight,mentalModel=model,decisiveFacts=facts,decisiveMutation=r['decisiveMutationConcept'],authorRationale=rationale);
 for o in c["options"]:
  if o["isBest"]:o["reasoningPattern"]=c["primaryPattern"]
 cases.append(c)
